waitSemaphores
  :: forall m
   . (MonadIO m)
  => Device
  -> SemaphoreWaitInfo
  -> Word64
  -> m (Outcome ())
waitSemaphores device waitInfo timeout =
  liftIO $ withArena \arena_ -> runAlloc arena_ do
    p_waitInfo :: Ptr () <- castPtr <$> new waitInfo
    r_ <-
      liftIO
        ( mkWaitSemaphores
            (checkCommandPtr "vkWaitSemaphores" device.cmds.pWaitSemaphores)
            (castPtr device.handle)
            p_waitInfo
            timeout
        )
    if r_ < 0 then
      pure (Err (openFromWire r_))
    else do
      pure (Ok (openFromWire r_) ())
